import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import './css/Login.css';
import logoImage from '../assets/aqi.webp';

function Login() {
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [isMobileView, setIsMobileView] = useState(window.innerWidth <= 768);
  const navigate = useNavigate();

  // CSRF Token Helper Function (single declaration)
  const getCsrfToken = () => {
    const cookies = document.cookie.split(';');
    for (let cookie of cookies) {
      const [name, value] = cookie.trim().split('=');
      if (name === 'csrftoken') {
        return decodeURIComponent(value);
      }
    }
    return null;
  };

  const API_BASE_URL =
    process.env.NODE_ENV === 'production'
      ? 'https://airaware-app-gcw7.onrender.com'
      : 'http://localhost:8000';

  useEffect(() => {
    // Fetch CSRF token when component mounts
    const fetchCsrfToken = async () => {
      try {
        await fetch(`${API_BASE_URL}/csrf/`, {
          credentials: 'include'
        });
      } catch (error) {
        console.error('Failed to fetch CSRF token', error);
      }
    };

    fetchCsrfToken();
  }, [API_BASE_URL]);

  useEffect(() => {
    const handleResize = () => setIsMobileView(window.innerWidth <= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError('');
    setSuccess('');
  };

  const handleSubmit = async (e) => {
  e.preventDefault();
  setError('');
  setSuccess('');
  setLoading(true);

  try {
    const csrfToken = getCsrfToken();

    const response = await fetch(`${API_BASE_URL}/api/user_login_api/`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRFToken': csrfToken,
      },
      credentials: 'include',
      body: JSON.stringify({
        username: formData.username,
        password: formData.password
      }),
    });

    // More detailed error logging
    if (!response.ok) {
      const errorText = await response.text();
      console.error('Server error response:', {
        status: response.status,
        statusText: response.statusText,
        body: errorText
      });
      throw new Error('Login request failed');
    }

    const data = await response.json();

    if (data.success) {
      // Log redirect information
      console.log('Redirect to:', data.redirect_to);
      
      localStorage.setItem('user', JSON.stringify({
      ...data.user,
      has_health_assessment: data.has_health_assessment
    }));
      
      // Always use data.redirect_to for navigation
      navigate(data.redirect_to);
    } else {
      setError(data.error || 'Login failed');
    }
  } catch (err) {
    console.error('Login error:', err);
    setError('Unable to connect to the server. Please try again.');
  } finally {
    setLoading(false);
  }
};
  // --- END: CORRECTED SUBMIT FUNCTION ---

  return (
    <div className="login-page">
      <nav className="navbar">
        <div className="navbar-content">
          <Link to="/" className="navbar-brand">
            <img
              src={logoImage}
              alt="AirAware"
              width={isMobileView ? '32' : '40'}
              height={isMobileView ? '32' : '40'}
            />
            AirAware
          </Link>
        </div>
      </nav>

      <section className="login-section">
        <div className="login-container">
          <div className="login-header">
            <h2>👤 User Login</h2>
            <p>Enter your credentials to continue</p>
          </div>

          {(success || error) && (
            <div className={`toast-notification ${success ? 'toast-success' : 'toast-error'}`}>
              <span>{success || error}</span>
              <button className="toast-close" onClick={() => { setSuccess(''); setError(''); }}>×</button>
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="username">Username</label>
              <input
                type="text"
                id="username"
                name="username"
                value={formData.username}
                onChange={handleChange}
                placeholder="Enter username"
                required
                disabled={loading}
              />
            </div>

            <div className="form-group">
              <label htmlFor="password">Password</label>
              <input
                type="password"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Enter password"
                required
                disabled={loading}
              />
            </div>

            <button
              type="submit"
              className="btn-primary"
              disabled={loading}
            >
              {/* <Link to="/dashboard"></Link>  <-- REMOVE THIS LINE */}
              {loading ? 'Logging in...' : 'Login'}
            </button>

            <div className="login-footer">
              <p>
                Don’t have an account? <Link to="/signup">Sign Up</Link>
              </p>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
}

export default Login;
